    /** Must execute the original native provider under the actual Root-held Menu or Gameplay scope. */
    @FunctionalInterface public interface NativeAccess { Response execute(Request request)throws IOException,InterruptedException; }
    /** Actual connected HELLO/observer packet, independently acquired by Root, never a user argument. */
    @FunctionalInterface public interface MountAccess { RawJson currentDiagnostics()throws IOException,InterruptedException; }
    private final NativeAccess nativeAccess;private final MountAccess mounts;private final Map<Method,NativeAccess> components;
    public FrontendCoaService(NativeAccess nativeAccess,MountAccess mounts){this.nativeAccess=Objects.requireNonNull(nativeAccess);this.mounts=Objects.requireNonNull(mounts);this.components=Map.of();}
    /** A finite component shares this sole request/response contract; no alias argument parser. */
    public record ComponentBinding(Set<Method> methods,NativeAccess service) {
        public ComponentBinding { methods=Set.copyOf(methods);Objects.requireNonNull(service);need(!methods.isEmpty()&&methods.size()<=7,"finite actual CoA component methods required");for(Method method:methods)need(method.ordinal()<=Method.VFS.ordinal(),"disk source method is owned by the sole shared service"); }
    }
    public FrontendCoaService(List<ComponentBinding> actualComponents) {
        var selected=new java.util.EnumMap<Method,NativeAccess>(Method.class);
        for(ComponentBinding component:List.copyOf(actualComponents))for(Method method:component.methods())need(selected.putIfAbsent(method,component.service())==null,"duplicate actual CoA component owner");
        components=Map.copyOf(selected);
        nativeAccess=request->{throw new IOException("actual CoA component is absent from this installed catalog: "+request.method().publicName());};
        mounts=()->{throw new IOException("actual current mounted-data source is absent from this installed catalog");};
    }
    /** Called only by the source-bound VFS component, with its actual validated current diagnostics. */
    public static Response projectVfs(Vfs request,RawJson actualDiagnostics)throws IOException {
        Objects.requireNonNull(request);Objects.requireNonNull(actualDiagnostics);return response(project(request,object(actualDiagnostics)));
    }
    public Response execute(Request request)throws IOException,InterruptedException {
        Objects.requireNonNull(request);NativeAccess component=components.get(request.method());if(component!=null)return component.execute(request);
        if(request instanceof Catalog c)return response(c.method()==Method.DEFINITION_CATALOG?definitionCatalog(c):c.method()==Method.CONFIGURED_CATALOG?configuredCatalog(c):resourceCatalog(c));
        if(request instanceof Asset a)return response(a.method()==Method.CONFIGURED_ASSET?configuredAsset(a):resourceAsset(a));
        if(request instanceof Definition d)return response(definition(d));
        if(request instanceof Directory d)return response(switch(d.method()){case LOAD_CONFIGURATION->loadConfiguration(d.directory());case DLC->dlc(d.directory());case RENDER_SUPPORT->renderSupport(d.directory());default->throw new IllegalArgumentException("invalid directory request");});
        if(request instanceof Vfs v)return response(project(v,object(mounts.currentDiagnostics())));
        return nativeAccess.execute(request);
    }
